export function leastInterval(tasks          , cooldown        )         {
if(!tasks.length)return 0;const counts=new Map               ();for(const t of tasks)counts.set(t,(counts.get(t)??0)+1);const max=Math.max(...counts.values()),ties=[...counts.values()].filter(x=>x===max).length;return Math.max(tasks.length,(max-1)*(cooldown+1)+ties);
}

